def candidate(events):
    return helper_1(events, event_key=lambda account, event_id, amount: event_id)

def helper_1(events, *, event_key=lambda account, event_id, amount: (account, event_id)):
    booked = {}
    for account, event_id, amount in events:
        booked.setdefault(event_key(account, event_id, amount), amount)
    return sum(booked.values())
